}
.result-card:hover {
    border-color: var(--orange);
    box-shadow: 0 2px 14px rgba(255, 107, 0, 0.15);
    transform: translateY(-1px);
}
.result-meta {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 6px;
    font-size: 12.5px;
}
.result-author { color: var(--orange-bright); font-weight: 700; font-size: 13.5px; }
.result-channel {
    color: var(--text-secondary);
    background: var(--bg-deepest);
    padding: 2px 8px;
    border-radius: 999px;
    font-weight: 500;
}
.result-time { color: var(--text-muted); margin-left: auto; }
.result-content {
    font-size: 14px;
    line-height: 1.5;
    color: var(--text-primary);
    word-break: break-word;
    white-space: pre-wrap;
}
.result-jump {
    margin-top: 8px;
    font-size: 12px;
    color: var(--text-muted);
}
.result-card:hover .result-jump { color: var(--orange); }

mark {
    background: var(--orange);
    color: #1a1006;
    font-weight: 700;
    border-radius: 3px;
    padding: 0 2px;
    box-shadow: 0 0 8px var(--orange-glow);
}

.search-more-wrap { flex-shrink: 0; padding: 6px 0 16px; text-align: center; }

/* =========================================================
   FUN FACTS MODE
   ========================================================= */
.facts-shell {
    flex: 1;
    overflow-y: auto;
    width: 100%;
    padding: 26px 24px 48px;
}
.facts-controls {
    max-width: 1100px;
    margin: 0 auto 24px;
}
.facts-title { font-size: 26px; font-weight: 800; }
.facts-sub { color: var(--text-muted); font-size: 14px; margin: 4px 0 16px; }

#facts-content { max-width: 1100px; margin: 0 auto; }

.facts-hero {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
    margin-bottom: 18px;
}
.hero-stat {
    background: linear-gradient(135deg, var(--bg-raised), var(--bg-base));
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 16px;
    text-align: center;
    transition: all 0.2s;
}
.hero-stat:hover { border-color: var(--orange); transform: translateY(-2px); }
.hero-stat-value {
    font-size: 26px;
    font-weight: 800;
    background: linear-gradient(90deg, var(--orange-bright), var(--orange-deep));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1.2;
    word-break: break-word;
}
.hero-stat-label {
    font-size: 11.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--text-muted);
    margin-top: 6px;
}

.facts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 16px;
}

.fact-card {
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 18px;
    animation: slide-in 0.3s ease both;
}
.fact-card-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 14px;
    color: var(--orange-bright);
}
.fact-card-title .fact-emoji { font-size: 18px; }

.bar-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}
.bar-label {
    width: 130px;
    flex-shrink: 0;
    font-size: 13px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: right;
    font-family: var(--font-mono);
}
.bar-track {
    flex: 1;
    height: 18px;
    background: var(--bg-deepest);
    border-radius: 4px;
    overflow: hidden;
}
.bar-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--orange-deep), var(--orange));
    border-radius: 4px;
    transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
    box-shadow: 0 0 8px rgba(255, 107, 0, 0.3);
}
.bar-count {
    width: 52px;
    flex-shrink: 0;
    font-size: 12px;
    color: var(--text-muted);
    font-family: var(--font-mono);
}

.fact-blockquote {
    background: var(--bg-deepest);
    border-left: 3px solid var(--orange);
    border-radius: 6px;
    padding: 12px 14px;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--text-secondary);
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 180px;
    overflow-y: auto;
}

.hour-chart {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    height: 90px;
    margin-top: 6px;
}
.hour-bar-wrap {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    height: 100%;
    justify-content: flex-end;
}
.hour-bar {
    width: 100%;
    background: linear-gradient(180deg, var(--orange), var(--orange-deep));
    border-radius: 3px 3px 0 0;
    min-height: 2px;
    transition: height 0.5s ease;
    opacity: 0.85;
}
.hour-bar-wrap:hover .hour-bar { opacity: 1; box-shadow: 0 0 8px var(--orange-glow); }
.hour-bar-wrap.peak .hour-bar { background: var(--orange-bright); opacity: 1; }
.hour-label { font-size: 8.5px; color: var(--text-muted); font-family: var(--font-mono); }

.fact-card.wide { grid-column: 1 / -1; }

/* =========================================================
   Responsive
   ========================================================= */
@media (max-width: 900px) {
    .topbar { gap: 12px; padding: 0 12px; }
    .topbar-stats { display: none; }
    .mode-tab { padding: 8px 12px; font-size: 13px; }
    .server-bar { display: none; }
    .sidebar { width: 200px; }
    .bar-label { width: 90px; }
}
@media (max-width: 640px) {
    .brand-name { display: none; }
    .sidebar { width: 160px; }
    .search-row { flex-direction: column; }
    .user-select { max-width: none; }
}
